// SetPluginSettings is the resolver for the setPluginSettings field.
func (r *mutationResolver) SetPluginSettings(ctx context.Context, name string, values []*model.PluginSettingInput) (*model.Plugin, error) {
	plugin, found := r.Plugins.Get(name)
	if !found {
		return nil, fmt.Errorf("plugin %q is not installed", name)
	}
	pluginValues := map[string]string{}
	for _, value := range values {
		pluginValues[value.Key] = value.Value
	}
	pluginValues = plugin.Meta.WithoutDefaultBaseURL(pluginValues)
	update := settings.Update{PluginSettings: map[string]map[string]string{name: pluginValues}}
	if _, err := r.Settings.Apply(ctx, update); err != nil {
		return nil, err
	}
	return r.pluginByName(name)
}

