// RecommendedFor is the resolver for the recommendedFor field.
func (r *personResolver) RecommendedFor(ctx context.Context, obj *model.Person, profileID string, limit *int) ([]*model.Title, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return nil, err
	}
	filmography, err := r.Library.Store.Filmography(ctx, obj.TmdbID, "")
	if err != nil {
		return nil, err
	}
	refs := make([]library.MediaRef, 0, len(filmography))
	for _, title := range filmography {
		refs = append(refs, library.MediaRef{MediaType: title.MediaType, MediaID: title.TMDBID})
	}
	ranked, err := r.Recommender.RankTitles(ctx, profile, refs)
	if err != nil {
		return nil, err
	}
	ranked = ranked[:min(len(ranked), clamp(valueOr(limit, 20), 50))]
	titles, err := r.Library.Store.Titles(ctx, ranked)
	if err != nil {
		return nil, err
	}
	return titleModels(titles), nil
}

