func (r *queryResolver) LikedTitles(ctx context.Context, profileID string, limit *int) ([]*model.Title, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return nil, err
	}
	ratings, err := r.Services.Profiles.Ratings(ctx, profile)
	if err != nil {
		return nil, err
	}
	refs := likedRefs(ratings, clamp(valueOr(limit, 30), 100))
	titles, err := r.titlesByRef(ctx, refs)
	if err != nil {
		return nil, err
	}
	return inRefOrder(refs, titles), nil
}

// Notifications is the resolver for the notifications field.
func (r *queryResolver) Notifications(ctx context.Context, profileID string, limit *int) ([]*model.Notification, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return nil, err
	}
	stored, err := r.Services.Notifications.List(ctx, profile, clamp(valueOr(limit, 30), 100))
	if err != nil {
		return nil, err
	}
	return r.notificationModels(ctx, stored)
}

// UnreadNotificationCount is the resolver for the unreadNotificationCount field.
func (r *queryResolver) UnreadNotificationCount(ctx context.Context, profileID string) (int, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return 0, err
	}
	return r.Services.Notifications.UnreadCount(ctx, profile)
}

// Downloads is the resolver for the downloads field.
func (r *queryResolver) Downloads(ctx context.Context, profileID string) ([]*model.Download, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return nil, err
	}
	stored, err := r.Services.Downloads.Store.List(ctx, profile)
	if err != nil {
		return nil, err
	}
	models := make([]*model.Download, 0, len(stored))
	for _, download := range stored {
		downloadModel, err := r.downloadModel(ctx, download)
		if err != nil {
			return nil, err
		}
		if downloadModel != nil {
			models = append(models, downloadModel)
		}
	}
	return models, nil
}

// DownloadsFolder is the resolver for the downloadsFolder field.
func (r *queryResolver) DownloadsFolder(ctx context.Context) (*string, error) {
	folder := r.Services.Downloads.Folder()
	if folder == "" {
		return nil, nil
	}
	return &folder, nil
}

// TogetherRoom is the resolver for the togetherRoom field.
