// Settings is the resolver for the settings field.
func (r *queryResolver) Settings(ctx context.Context) (*model.Settings, error) {
	return r.settingsModel(r.Services.Settings.Cached()), nil
}

// CheckTmdbKey is the resolver for the checkTmdbKey field.
func (r *queryResolver) CheckTmdbKey(ctx context.Context, key string) (bool, error) {
	return r.TMDB.CheckKey(ctx, strings.TrimSpace(key))
}

// Plugins is the resolver for the plugins field.
func (r *queryResolver) Plugins(ctx context.Context) ([]*model.Plugin, error) {
	pluginSettings := r.Services.Settings.Cached().PluginSettings
	models := []*model.Plugin{}
	for _, plugin := range r.Services.Plugins.All() {
		models = append(models, pluginModel(plugin, r.Services.Plugins, pluginSettings[plugin.Meta.Name]))
	}
	slices.SortFunc(models, func(left, right *model.Plugin) int { return strings.Compare(left.Name, right.Name) })
	return models, nil
}

// Status is the resolver for the status field.
func (r *queryResolver) Status(ctx context.Context) (*model.Status, error) {
	return &model.Status{
		TmdbConfigured: r.TMDB.Configured(),
		VpnConnected:   r.VpnConnected(),
		RequireVpn:     r.Services.Settings.Cached().RequireVpn,
	}, nil
}

// Episodes is the resolver for the episodes field.
func (r *seasonResolver) Episodes(ctx context.Context, obj *model.Season) ([]*model.Episode, error) {
	_, seasonID, err := parseID(obj.ID, "season")
	if err != nil {
		return nil, err
	}
	season, err := r.Library.Store.SeasonByID(ctx, seasonID)
	if err != nil || season == nil {
		return nil, err
	}
	episodes, err := r.Library.EnsureSeason(ctx, season.SeriesID, season.SeasonNumber)
	if err != nil {
		return nil, err
	}
	models := make([]*model.Episode, 0, len(episodes))
	for _, episode := range episodes {
		models = append(models, episodeModel(episode))
	}
	return models, nil
}

// Streams is the resolver for the streams field.
func (r *subscriptionResolver) Streams(ctx context.Context, id string) (<-chan *model.StreamUpdate, error) {
	ref, err := parseMedia(id, library.MediaTypeMovie, library.MediaTypeEpisode)
	if err != nil {
		return nil, err
	}
	if err := r.requireVpnIfConfigured(); err != nil {
		return nil, err
	}
	return r.subscribeStreams(ctx, ref)
}

// Together is the resolver for the together field.
func (r *subscriptionResolver) Together(ctx context.Context) (<-chan *model.TogetherUpdate, error) {
	return togetherUpdates(ctx, r.Services.Together.Subscribe(ctx)), nil
}

