// Seasons is the resolver for the seasons field.
func (r *titleResolver) Seasons(ctx context.Context, obj *model.Title) ([]*model.Season, error) {
	if obj.MediaType != model.MediaTypeSeries {
		return []*model.Season{}, nil
	}
	seasons, err := r.Library.Store.Seasons(ctx, obj.TmdbID)
	if err != nil {
		return nil, err
	}
	models := make([]*model.Season, 0, len(seasons))
	for _, season := range seasons {
		models = append(models, seasonModel(season))
	}
	return models, nil
}

// SeasonCount is the resolver for the seasonCount field.
func (r *titleResolver) SeasonCount(ctx context.Context, obj *model.Title) (int, error) {
	if obj.MediaType != model.MediaTypeSeries {
		return 0, nil
	}
	return r.Library.Store.SeasonCount(ctx, obj.TmdbID)
}

// Streams is the resolver for the streams field.
func (r *titleResolver) Streams(ctx context.Context, obj *model.Title) ([]*model.Stream, error) {
	if obj.MediaType != model.MediaTypeMovie {
		return []*model.Stream{}, nil
	}
	return r.streamsOf(ctx, titleRef(obj))
}

