// Rating is the resolver for the rating field.
func (r *titleResolver) Rating(ctx context.Context, obj *model.Title, profileID string) (*float64, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return nil, err
	}
	rating, err := r.Profiles.Rating(ctx, profile, titleRef(obj))
	if err != nil || rating == nil {
		return nil, err
	}
	return &rating.Rating, nil
}

// InWatchlist is the resolver for the inWatchlist field.
func (r *titleResolver) InWatchlist(ctx context.Context, obj *model.Title, profileID string) (bool, error) {
	profile, err := parseProfile(profileID)
	if err != nil {
		return false, err
	}
	return r.Profiles.InWatchlist(ctx, profile, titleRef(obj))
}

